def permutation_coefficient(n, k):
    if k == 0:
        return 1
    else:
        return n * permutation_coefficient(n-1, k-1)

def count_element_freq(nested_tuple):
    freq = {}
    for elem in nested_tuple:
        if isinstance(elem, tuple):
            freq.update(count_element_freq(elem))
        else:
            freq[elem] = freq.get(elem, 0) + 1
    return freq

def count_element_freq(tup):
    freq_dict = {}
    for element in tup:
        if isinstance(element, tuple):
            for sub_element in element:
                freq_dict[sub_element] = freq_dict.get(sub_element, 0) + 1
        else:
            freq_dict[element] = freq_dict.get(element, 0) + 1
